/* ═══════════════════════════════════════════════════════════
   SEARCH — Precomputed index برای سرعت بالا
   ═══════════════════════════════════════════════════════════ */

function normalizeText(text: string): string {
  return text
    .replace(/[\u200c\u200e\u200f]/g, ' ')
    .replace(/[يى]/g, 'ی')
    .replace(/[ك]/g, 'ک')
    .replace(/[أإآٱ]/g, 'ا')
    .replace(/[ة]/g, 'ه')
    .replace(/[\u064B-\u065F]/g, '')
    .replace(/[^\p{L}\p{N}\s]/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase();
}

type IndexedEntry = {
  readonly entry: KnowledgeEntry;
  readonly normalizedKeywords: readonly { readonly text: string; readonly length: number }[];
};

/* Precompute at module load */
const INDEX: readonly IndexedEntry[] = KNOWLEDGE.map((entry) => ({
  entry,
  normalizedKeywords: entry.keywords.map((k) => {
    const n = normalizeText(k);
    return { text: n, length: n.length };
  }),
}));

export function searchKnowledge(query: string): KnowledgeEntry | null {
  const normalized = normalizeText(query);
  if (!normalized || normalized.length < 2) return null;

  let bestEntry: KnowledgeEntry | null = null;
  let bestScore = 0;

  for (const { entry, normalizedKeywords } of INDEX) {
    let score = 0;

    for (const k of normalizedKeywords) {
      if (k.length === 0) continue;

      if (normalized === k.text) score += k.length * 4;
      else if (normalized.includes(k.text)) score += k.length * 2;
      else if (k.text.includes(normalized) && normalized.length >= 3) {
        score += normalized.length * 1.5;
      }
    }

    if (score > bestScore) {
      bestScore = score;
      bestEntry = entry;
    }
  }

  if (bestScore < 6) return null;
  return bestEntry;
}

export function getEntriesByCategory(
  category: KnowledgeCategory,
): readonly KnowledgeEntry[] {
  return KNOWLEDGE.filter((e) => e.category === category);
}

export function getKnowledgeStats() {
  const categories = new Set(KNOWLEDGE.map((e) => e.category));
  return {
    total: KNOWLEDGE.length,
    categories: categories.size,
  };
}